    sum1 = a * a + b * b
    sum2 = c * c + d * d
    n = sum1 * sum2
    solutions = []
    for i in range(int(math.sqrt(n)) + 1):
        j = math.isqrt(n - i * i)
        if i * i + j * j == n:
            solutions.append([i, j])
    return solutions

