        target_row = row3
    elif target in row4:
        target_row = row4
    elif target in row5:
        target_row = row5
    else:
        return 0  # Invalid character

    if current_row == target_row:
        return abs(row1.index(current) - row1.index(target))
    else:
        return min(abs(row1.index(current) - row1.index(target)), abs(row2.index(current) - row2.index(target)),
