def navigate_to(keyboard, current, target):
    if current == target:
        return 0
    if target == 'aA':
        return 1 + navigate_to(keyboard, 'a', 'A')
    if target == 'SP':
        return 1 + navigate_to(keyboard, ' ', 'SP')
    if target == 'a':
        return 1 + navigate_to(keyboard, 'SP', 'a')
    if target == 'A':
        return 1 + navigate_to(keyboard, 'SP', 'A')
    if target == ' ':
        return 1 + navigate_to(keyboard, 'SP', ' ')

    distances = []
    for key in keyboard:
