def calculate_total_spent(bill):
    total_spent = sum(bill.values())
    return total_spent

def calculate_each_share(bill, total_spent):
    number_of_people = len(bill)
    each_share = total_spent / number_of_people
    return each_share

def calculate_owes_and_receives(bill, each_share):
    owes_and_receives = {}
    for name, spent in bill.items():
        difference = spent - each_share
        owes_and_receives[name] = round(difference, 2)
    return owes_and_receives

def split_the_bill(x):
    total_spent = calculate_total_spent(x)
    each_share = calculate_each_share(x, total_spent)
    result = calculate_owes_and_receives(x, each_share)
    return result

